import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Petabyte Scale Object Storage Service Using Ceph in A Private Cloud - Varada Kari","description":"","frontmatter":{"title":"Petabyte Scale Object Storage Service Using Ceph in A Private Cloud - Varada Kari","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-24T00:00:00.000Z","tags":["Ceph","分布式存储","对象存储","集群监控","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Petabyte_Scale_Object_Storage_Service_Using_Ceph_in_A_Private_Cloud_-_Varada_Kari.md","filePath":"posts/2018/Petabyte_Scale_Object_Storage_Service_Using_Ceph_in_A_Private_Cloud_-_Varada_Kari.md","lastUpdated":1780459816000}'),r={name:"posts/2018/Petabyte_Scale_Object_Storage_Service_Using_Ceph_in_A_Private_Cloud_-_Varada_Kari.md"};function o(h,a,n,p,_,s){return i(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><p>[请填写会议具体时间]</p><h4 id="会议地点" tabindex="-1">会议地点 <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点&quot;">​</a></h4><p>[请填写会议地点]</p><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Barda（Flipkart）</li><li>Flipkart 团队成员</li></ul><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><ul><li>Flipkart 与 Ceph 的合作历程</li><li>Ceph 在 Flipkart 内部部署与使用</li><li>面临的挑战及解决方案</li><li>Ceph 的 QoS 机制与集群监控</li></ul><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><h5 id="一、flipkart-公司介绍" tabindex="-1">一、Flipkart 公司介绍 <a class="header-anchor" href="#一、flipkart-公司介绍" aria-label="Permalink to &quot;一、Flipkart 公司介绍&quot;">​</a></h5><ul><li>Flipkart 是印度最大的电子商务公司，业务涵盖了从数据存储到电商平台等多个领域。他们使用 Ceph 作为其对象存储服务，已部署近三年，拥有两个数据中心，每个数据中心约 20000 台主机，完全虚拟化基础设施。</li></ul><h5 id="二、ceph-部署与使用" tabindex="-1">二、Ceph 部署与使用 <a class="header-anchor" href="#二、ceph-部署与使用" aria-label="Permalink to &quot;二、Ceph 部署与使用&quot;">​</a></h5><ul><li>Flipkart 使用 Ceph 作为对象存储服务，重点在于数据持久性和可靠性。</li><li>部署了三个不同类型的工作负载： <ul><li>低延迟平台：用于存储小对象，关注低延迟。</li><li>备份平台：用于备份关键数据库，优化带宽。</li><li>归档平台：用于存储需要长期保存的数据，优化性能和容量。</li></ul></li><li>使用多个集群，每个集群包含多个节点，包括 Mon、OSD、MDS 和 RGW。</li></ul><h5 id="三、挑战与解决方案" tabindex="-1">三、挑战与解决方案 <a class="header-anchor" href="#三、挑战与解决方案" aria-label="Permalink to &quot;三、挑战与解决方案&quot;">​</a></h5><ul><li><strong>写入压力过大</strong>：通过将日志迁移到 SSD 和引入写回缓存来缓解。</li><li><strong>元数据问题</strong>：通过手动分片和禁用日志池来解决。</li><li><strong>应用错误</strong>：通过引入速率限制和检查桶创建请求来解决。</li><li><strong>数据丢失</strong>：通过开发离线工具来查找和删除丢失的对象。</li><li><strong>升级问题</strong>：从 Hammer 升级到 Luminous 过程中遇到了挑战，目前正在寻找解决方案。</li></ul><h5 id="四、qos-机制" tabindex="-1">四、QoS 机制 <a class="header-anchor" href="#四、qos-机制" aria-label="Permalink to &quot;四、QoS 机制&quot;">​</a></h5><ul><li>使用四层保障机制确保服务质量： <ul><li>负载均衡器：平衡负载。</li><li>Nginx 层：分离读写请求。</li><li>速率限制器：限制用户请求。</li><li>分区：将节点物理隔离。</li></ul></li></ul><h5 id="五、集群监控" tabindex="-1">五、集群监控 <a class="header-anchor" href="#五、集群监控" aria-label="Permalink to &quot;五、集群监控&quot;">​</a></h5><ul><li>使用 OpenTSDB 和 Grafana 进行监控，收集系统统计信息、数据库统计信息和 I/O 统计信息。</li><li>使用警报系统来通知集群问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化 Ceph 集群，解决升级问题。</li><li>开发更多工具来提高集群可靠性和性能。</li><li>探索端到端 QoS 机制。</li></ul><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>Flipkart 使用 Ceph 作为其核心存储解决方案，取得了显著的成果。然而，仍面临一些挑战，需要进一步改进和优化。</p><p>[错误、误解或遗漏的重要信息]</p><ul><li><p>原始总结中未提及 Flipkart 的具体业务范围，而原始字幕中提到了 Flipkart 在数据存储和电商平台等多个领域。</p></li><li><p>原始字幕中提到了 Flipkart 使用 Ceph 作为对象存储服务，而原始总结中未明确指出。</p></li><li><p>原始字幕中提到了 Flipkart 使用 Ceph 作为其核心存储解决方案，而原始总结中未明确指出。</p></li><li><p>保留了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p></li><li><p>修正了原始总结中未提及的 Flipkart 业务范围和 Ceph 服务使用情况。</p></li><li><p>确保了保留计算机科学/ceph相关领域的英文原文关键词。</p></li><li><p>优化了语言表达，使内容更加准确和清晰。</p></li></ul>',26)])])}const c=e(r,[["render",o]]);export{u as __pageData,c as default};
